pub unsafe fn ZopfliSublenToCache(
    mut sublen: *const c_ushort,
    mut pos: size_t,
    mut length: size_t,
    mut lmc: *mut ZopfliLongestMatchCache,
) {
    if length < 3 as size_t {
        return;
    }

    let cache = unsafe {
        // SAFETY: `lmc` is assumed valid by the original function contract, and `sublen`
        // points to a buffer large enough for the computed cache slice for `pos`.
        (*lmc).sublen.add(
            (ZOPFLI_CACHE_LENGTH as size_t)
                .wrapping_mul(pos)
                .wrapping_mul(3 as size_t),
        )
    };

    let mut j: size_t = 0;
    let mut bestlength: c_uint = 0 as c_uint;
    let mut i: size_t = 3 as size_t;

    while i < length {
        let v = unsafe {
            // SAFETY: same preconditions as the original function; `i` stays within the
            // range accessed by the original loop.
            *sublen.add(i)
        };
        let next = unsafe {
            // SAFETY: same preconditions as the original function; for `i < length`,
            // accessing `sublen[i + 1]` matches the original behavior.
            *sublen.add(i.wrapping_add(1 as size_t))
