        if v != next {
            let base = j.wrapping_mul(3 as size_t);
            unsafe {
                // SAFETY: `base..base+2` is within the fixed-size cache region as long as
                // `j < ZOPFLI_CACHE_LENGTH`, which is maintained before increment/break.
                *cache.add(base) = i.wrapping_sub(3 as size_t) as c_uchar;
                *cache.add(base.wrapping_add(1 as size_t)) = (v as c_int % 256 as c_int) as c_uchar;
                *cache.add(base.wrapping_add(2 as size_t)) =
                    ((v as c_int >> 8 as c_int) % 256 as c_int) as c_uchar;
            }
            bestlength = i as c_uint;
            j = j.wrapping_add(1);
            if j >= ZOPFLI_CACHE_LENGTH as size_t {
