            // SAFETY: `j < ZOPFLI_CACHE_LENGTH` guarantees these writes stay inside the
            // cache region for this position.
            *cache.add(base) = length.wrapping_sub(3 as size_t) as c_uchar;
            *cache.add(base.wrapping_add(1 as size_t)) = (v as c_int % 256 as c_int) as c_uchar;
            *cache.add(base.wrapping_add(2 as size_t)) =
